function validWorld(w){return !!w&&Number.isInteger(w.day)&&w.day>=1&&w.day<=100&&Number.isInteger(w.seed)&&Array.isArray(w.team)&&w.team.length===12&&w.team.every(p=>Number.isInteger(p.id)&&Number.isFinite(p.energy)&&Number.isFinite(p.skill)&&Number.isFinite(p.relation)&&Number.isFinite(p.motivation))&&Array.isArray(w.tasks)&&w.tasks.every(t=>Number.isInteger(t.id)&&Number.isInteger(t.assigned)&&t.assigned>=0&&t.assigned<12&&Number.isFinite(t.remaining)&&Number.isFinite(t.due)&&['open','done'].includes(t.status))&&w.metrics&&['trust','wellbeing','delivery','budget'].every(k=>Number.isFinite(w.metrics[k]))&&w.policy&&['balanced','deadline'].includes(w.policy.priority)&&Array.isArray(w.log)&&Array.isArray(w.events)}
function load(){let s={};try{s=JSON.parse(localStorage.getItem('leadership-empire-prototype-v2')||localStorage.getItem('leadership-empire-prototype-v1'))||{}}catch{}if(typeof s!=='object'||Array.isArray(s)||!s)s={};if(s.world&&!validWorld(s.world))s={};if(s.config&&(!DEPARTMENTS[s.config.department]||!ORGS[s.config.org]||!SIZES[s.config.size]))s={};const next={...DEFAULT,...s,history:Array.isArray(s.history)?s.history:[],relations:Array.isArray(s.relations)&&s.relations.length===12?s.relations:DEFAULT.relations.slice(),energy:Array.isArray(s.energy)&&s.energy.length===12?s.energy:DEFAULT.energy.slice()};if(!next.world){next.world=LeadershipEngine.create(next.config||DEFAULT.config);for(const k of ['trust','wellbeing','delivery','budget'])next.world.metrics[k]=next[k];next.world.day=next.day;next.world.tasks.forEach(task=>{task.created+=next.day-1;task.due+=next.day-1});next.world.team.forEach((person,i)=>{person.energy=next.energy[i];person.relation=next.relations[i]})}if((next.world.schema||1)<2){next.world.schema=2;next.world.onTime=next.world.completed||0;next.world.metrics.quality=70;next.world.metrics.learning=30;next.world.team.forEach((person,i)=>{person.specialty=i%5});next.world.tasks.forEach(task=>{task.category=Math.max(0,(LeadershipEngine.CATALOG[next.world.department]||LeadershipEngine.CATALOG.it).findIndex(type=>task.title.startsWith(type)))})}return next}
function save(){localStorage.setItem('leadership-empire-prototype-v2',JSON.stringify(state))}
function val(k,n){state[k]=Math.min(100,Math.max(0,state[k]+n));if(state.world&&k in state.world.metrics)state.world.metrics[k]=state[k]}
function syncWorld(){for(const key of ['trust','wellbeing','delivery','budget'])state[key]=Math.round(state.world.metrics[key]);state.energy=state.world.team.map(t=>Math.round(t.energy));state.relations=state.world.team.map(t=>Math.round(t.relation))}
