function applyChoice(i){if(state.stage!==0)return;state.choice=i;state.stage=1;const impact=[{trust:-8,wellbeing:-6,delivery:5},{trust:7,wellbeing:5,delivery:-2},{trust:2,wellbeing:-2,delivery:3}][i];Object.entries(impact).forEach(([k,n])=>val(k,n));state.history.push(['Dag '+state.day,['Formel påtale','Undersøgende samtale','Specialistrolle'][i]]);LeadershipLearning.practice(state,'communication','Den stærke specialist');save();render()}
function applyFollowup(i){if(state.stage!==1)return;state.followup=i;state.stage=2;const impact=[{trust:4,wellbeing:5,delivery:3,budget:-4},{trust:-6,wellbeing:-7,delivery:6,budget:0},{trust:2,wellbeing:1,delivery:-3,budget:0}][i];Object.entries(impact).forEach(([k,n])=>val(k,n));state.history.push(['Dag '+state.day,['Fælles udviklingsplan','Hurtig håndhævelse','Afvent og observer'][i]]);LeadershipLearning.practice(state,'coaching','Opfølgning med specialist');save();render()}
function advance(){if(state.day>=100||state.eventOpen||state.crisis.fired)return;LeadershipEngine.advance(state.world);state.day=state.world.day;syncWorld();LeadershipConsequences.tick(state);LeadershipInitiatives.tick(state);if(state.stage===2&&state.day>=14)state.stage=3;const next=state.crisis.schedule[state.crisis.cursor];if(next&&state.day>=next.day){state.crisis.open=true;state.eventOpen=true;state.view='decisions'}else if(state.day>=15&&state.stage===3&&!state.eventOpen&&state.day-state.lastEventDay>=5&&state.eventIndex<EVENTS.length+LeadershipScenarios.count(config().department)){state.eventOpen=true;state.view='decisions'}LeadershipAdvisors.advance(state);LeadershipPerformance.record(state);save();render()}
function advanceWeek(){for(let i=0;i<7&&state.day<100;i++){if(state.eventOpen||state.crisis.fired||state.stage===0||state.stage===1)break;advance();if(state.eventOpen)break}}
function resolveEvent(choice){
 if(!state.eventOpen)return;
 const ev=scenario(),opt=ev?.options?.[choice];if(!opt)return;
 if(state.crisis.open){
  const result=LeadershipCrises.resolve(state.crisis,config(),choice);if(!result)return;
  for(const [k,n] of Object.entries(result.impact))val(k,n);
  state.history.push(['Dag '+state.day,ev.title+' — '+opt[0]]);
  state.eventOpen=false;
  LeadershipLearning.practice(state,'crisis',ev.title);
  if(result.fired){LeadershipPerformance.record(state,true);state.view='performance'}
  save();render();return;
 }
 for(const [k,n] of Object.entries(opt[2]))val(k,n);
 for(const i of opt[3])state.world.team[i].relation=LeadershipEngine.cap(state.world.team[i].relation+opt[4]);
 const personalityTopic=state.eventIndex===0?'conflict':state.eventIndex===2?'change':'workload';
 LeadershipPersonalities.decision(state,opt[3],personalityTopic,choice);
 syncWorld();state.history.push(['Dag '+state.day,ev.title+' — '+opt[0]]);
 const type=['conflict','workload','change'][state.eventIndex];
 if(type)LeadershipConsequences.start(state,type,choice,ev.title);
 state.eventIndex++;state.eventOpen=false;state.lastEventDay=state.day;
 const topic=/budget|økonomi/i.test(ev.title)?'finance':/konflikt|uenig|ansvar/i.test(ev.title)?'conflict':/automat|ændring|proces|release/i.test(ev.title)?'change':/direktion|ledermøde/i.test(ev.title)?'strategy':'motivation';
 LeadershipLearning.practice(state,topic,ev.title);
 save();render();
}
function startCareer(settings){if(!DEPARTMENTS[settings.department]||!ORGS[settings.org]||!SIZES[settings.size])return false;const gameConfig={...DEFAULT.config,...settings,...LeadershipCrises.settings(settings)};if(!LeadershipCrises.POSITION[gameConfig.position]||!LeadershipCrises.EXPERIENCE[gameConfig.experience]||!LeadershipCrises.RISK[gameConfig.risk]||!['off','gentle','normal','strict'].includes(gameConfig.accountability))return false;state={...DEFAULT,history:[],relations:DEFAULT.relations.slice(),energy:DEFAULT.energy.slice(),academy:{selected:0,answers:{},notes:{},completed:[]},advisors:LeadershipAdvisors.initial(),performance:LeadershipPerformance.initial(),learning:LeadershipLearning.initial(),consequences:LeadershipConsequences.initial(),peopleDynamics:LeadershipPersonalities.initial(),initiatives:LeadershipInitiatives.initial(),config:gameConfig,crisis:LeadershipCrises.create(gameConfig),budget:settings.org==='ngo'?65:settings.org==='private'?85:78,world:LeadershipEngine.create(gameConfig)};syncWorld();save();render();return true}
function academySelect(index){if(index<0||index>=LeadershipAcademy.modules.length)return;state.academy.selected=index;save();render()}
