async function importGame(file){if(!file)return false;try{const data=JSON.parse(await file.text()),candidate=data.game;if(data.format!=='leadership-empire-save'||data.version!==1||!candidate||!Number.isInteger(candidate.day)||candidate.day<1||candidate.day>100||candidate.day!==candidate.world?.day||!validWorld(candidate.world)||!DEPARTMENTS[candidate.config?.department]||!ORGS[candidate.config?.org]||!SIZES[candidate.config?.size]||candidate.config.department!==candidate.world.department||!Array.isArray(candidate.history))throw Error('Ukendt eller ugyldig gemmefil');if(!confirm('Indlæs gemmefilen? Det nuværende spil bliver erstattet.'))return false;state={...DEFAULT,...candidate,config:{...DEFAULT.config,...candidate.config},crisis:candidate.crisis||LeadershipCrises.migrate(candidate.config,candidate.day),advisors:LeadershipAdvisors.normalize(candidate.advisors),performance:LeadershipPerformance.normalize(candidate.performance),learning:LeadershipLearning.normalize(candidate.learning),consequences:LeadershipConsequences.normalize(candidate.consequences),peopleDynamics:LeadershipPersonalities.normalize(candidate.peopleDynamics),initiatives:LeadershipInitiatives.normalize(candidate.initiatives),academy:{...DEFAULT.academy,...(candidate.academy||{})}};syncWorld();save();render();return true}catch(error){alert('Kunne ikke indlæse spil: '+error.message);return false}}
