function finalReport(){const w=LeadershipEngine.summary(state.world),score=Math.round((state.trust+state.wellbeing+state.delivery+state.budget+w.metrics.quality)/5),label=score>=75?'Stærk balance':score>=55?'På vej mod stabil drift':'Kræver ny prioritering';if(state.crisis.fired)return `${crisisArtHTML('fired')}<div class="result-card fired-result"><strong>DU ER F*CKING FYRET!</strong><p>Din karriere sluttede på dag ${state.day}.</p><p>${escapeHTML(state.crisis.reason)}</p><p>Det er en fiktiv konsekvens i spillet. Se dine valg i historikken, eller start en ny karriere med andre indstillinger.</p><button class="btn primary" id="fired-restart">Prøv igen →</button></div>`;return `${crisisArtHTML('victory')}<div class="result-card"><strong>100 dage gennemført · ${score}/100</strong><p>${label}. Din evaluering bygger på fem spilindikatorer og er ikke en psykometrisk ledertest.</p><div class="statline"><span>Uforudsete hændelser</span><b>${state.crisis.resolved.length}</b></div><div class="statline"><span>Afsluttede opgaver</span><b>${w.completed}</b></div><div class="statline"><span>Åbne og forfaldne</span><b>${w.open} / ${w.overdue}</b></div><div class="statline"><span>Vigtige ledelsesvalg</span><b>${state.history.length}</b></div><p>Undersøg hvilke valg der påvirkede relationer, kapacitet og kvalitet. Prøv eventuelt samme afdeling med en anden strategi.</p><button class="btn primary" data-go="insights">Se ledelsesrapport →</button></div>`}
